def semver_sort(versions):
    def parse(v):
        # separate build metadata
        plus_idx = v.find('+')
        if plus_idx != -1:
            main_part = v[:plus_idx]
        else:
            main_part = v

        dash_idx = main_part.find('-')
        if dash_idx != -1:
            core = main_part[:dash_idx]
            prerelease = main_part[dash_idx+1:]
        else:
            core = main_part
            prerelease = None

        parts = core.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

        if prerelease is None:
            has_pre_flag = 1  # no prerelease sorts after
            pre_key = []
        else:
            has_pre_flag = 0  # has prerelease sorts before
            ids = prerelease.split('.')
            pre_key = []
            for ident in ids:
                if ident.isdigit():
                    pre_key.append((0, int(ident)))
                else:
                    pre_key.append((1, ident))

        return (major, minor, patch, has_pre_flag, pre_key)

    return sorted(versions, key=parse)

